(function() {
    'use strict';

    class LinAlgFinanceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'LinAlgFinance: Matrix Operations Lab';
            this.version = '1.0.0';

            this.MODULES = [
                {
                    titleKey: 'mod1_title',
                    briefKey: 'mod1_brief',
                    input1Key: 'mod1_input1',
                    input1Hint: 'mod1_hint1',
                    input1Min: 0, input1Max: 80, input1Step: 1, input1Default: 0,
                    input2Key: 'mod1_input2',
                    input2Hint: 'mod1_hint2',
                    input2Min: 0, input2Max: 80, input2Step: 1, input2Default: 60,
                    input2Visible: true,
                    matrixFn: '_matrixModule1'
                },
                {
                    titleKey: 'mod2_title',
                    briefKey: 'mod2_brief',
                    input1Key: 'mod2_input1',
                    input1Hint: 'mod2_hint1',
                    input1Min: 1, input1Max: 6, input1Step: 1, input1Default: 4,
                    input2Visible: false,
                    matrixFn: '_matrixModule2'
                },
                {
                    titleKey: 'mod3_title',
                    briefKey: 'mod3_brief',
                    input1Key: 'mod3_input1',
                    input1Hint: 'mod3_hint1',
                    input1Min: 50, input1Max: 95, input1Step: 1, input1Default: 75,
                    input2Key: 'mod3_input2',
                    input2Hint: 'mod3_hint2',
                    input2Min: 5, input2Max: 30, input2Step: 1, input2Default: 10,
                    input2Visible: true,
                    matrixFn: '_matrixModule3'
                },
                {
                    titleKey: 'mod4_title',
                    briefKey: 'mod4_brief',
                    input1Key: 'mod4_input1',
                    input1Hint: 'mod4_hint1',
                    input1Min: 50, input1Max: 500, input1Step: 10, input1Default: 300,
                    input2Key: 'mod4_input2',
                    input2Hint: 'mod4_hint2',
                    input2Min: 50, input2Max: 500, input2Step: 10, input2Default: 250,
                    input2Visible: true,
                    matrixFn: '_matrixModule4'
                },
                {
                    titleKey: 'mod5_title',
                    briefKey: 'mod5_brief',
                    input1Key: 'mod5_input1',
                    input1Hint: 'mod5_hint1',
                    input1Min: 1, input1Max: 5, input1Step: 1, input1Default: 4,
                    input2Visible: false,
                    matrixFn: '_matrixModule5'
                }
            ];
        }

        // ── Matrix display helpers ───────────────────────────────
        _bindLivePreview() {
            if (this._lpBound) return;
            var self = this;
            ['input1', 'input2'].forEach(function (id) {
                var el = document.getElementById(id);
                if (el) el.addEventListener('input', function () { self._updateLivePreview(); });
            });
            this._lpBound = true;
            this._updateLivePreview();
        }

        _updateLivePreview() {
            var el = document.getElementById('livePreview');
            if (!el || !window.mySimulation) return;
            var state = window.mySimulation.state;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.MODULES.length - 1);
            var mod = this.MODULES[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);
            var i1El = document.getElementById('input1');
            var i2El = document.getElementById('input2');
            if (!i1El) return;
            var d = { input1: parseFloat(i1El.value), input2: i2El ? parseFloat(i2El.value) : NaN };
            if (isNaN(d.input1) || (mod.input2Visible && isNaN(d.input2))) { el.innerHTML = ''; return; }
            var r, html = '';
            if (idx === 0) {
                r = this._calcModule1(d);
                html = t('mod1_fb_sharpe') + ': <strong>' + r.sharpe.toFixed(3) + '</strong> &middot; '
                     + t('mod1_fb_return') + ' ' + (r.portReturn * 100).toFixed(1) + '% &middot; '
                     + t('mod1_fb_risk') + ' ' + (r.portRisk * 100).toFixed(1) + '%';
            } else if (idx === 1) {
                r = this._calcModule2(d);
                html = t('mod2_explained') + ': <strong>' + (r.explainedVariance * 100).toFixed(1) + '%</strong> &middot; '
                     + t('mod2_fb_loss') + ' ' + (r.infoLoss * 100).toFixed(1) + '%';
            } else if (idx === 2) {
                r = this._calcModule3(d);
                html = t('mod3_active') + ': <strong>' + (r.steadyActive * 100).toFixed(1) + '%</strong>';
            } else if (idx === 3) {
                r = this._calcModule4(d);
                html = t('mod4_dist') + ': <strong>' + r.distance.toFixed(0) + '</strong> ('
                     + t('mod4_mfg') + ' ' + r.totalOutput1.toFixed(0) + ', ' + t('mod4_svc') + ' ' + r.totalOutput2.toFixed(0) + ')';
            } else {
                r = this._calcModule5(d);
                html = t('mod5_accuracy_lbl') + ': <strong>' + (r.accuracy * 100).toFixed(1) + '%</strong>';
            }
            el.innerHTML = html;
        }

        _renderMatrix(label, rows) {
            var html = '<div class="matrix-wrapper"><div class="matrix-label">' + label + '</div>';
            html += '<table class="matrix">';
            for (var i = 0; i < rows.length; i++) {
                html += '<tr>';
                for (var j = 0; j < rows[i].length; j++) {
                    html += '<td>' + rows[i][j] + '</td>';
                }
                html += '</tr>';
            }
            html += '</table></div>';
            return html;
        }

        _renderDataTable(headers, rows) {
            var html = '<table class="table table-sm data-table"><thead><tr>';
            for (var h = 0; h < headers.length; h++) {
                html += '<th>' + headers[h] + '</th>';
            }
            html += '</tr></thead><tbody>';
            for (var i = 0; i < rows.length; i++) {
                html += '<tr>';
                for (var j = 0; j < rows[i].length; j++) {
                    html += '<td>' + rows[i][j] + '</td>';
                }
                html += '</tr>';
            }
            html += '</tbody></table>';
            return html;
        }

        _matrixModule1() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var html = this._renderDataTable(
                [t('mod1_asset'), t('mod1_return'), t('mod1_risk')],
                [
                    ['Tech',        '12.0%', '20.0%'],
                    [t('mod1_bonds'), '4.0%',  '5.0%'],
                    [t('mod1_realestate'), '8.0%', '15.0%']
                ]
            );
            html += '<br>' + this._renderMatrix(
                t('mod1_covmatrix') + ' (\u03A3)',
                [
                    ['0.0400', '0.0060', '0.0120'],
                    ['0.0060', '0.0025', '0.0030'],
                    ['0.0120', '0.0030', '0.0225']
                ]
            );
            return html;
        }

        _matrixModule2() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var eigenvalues = [3.20, 1.80, 0.60, 0.25, 0.10, 0.05];
            var total = 6.0;
            var cumul = 0;
            var rows = [];
            for (var i = 0; i < eigenvalues.length; i++) {
                cumul += eigenvalues[i];
                rows.push([
                    '\u03BB' + (i + 1),
                    eigenvalues[i].toFixed(2),
                    (eigenvalues[i] / total * 100).toFixed(1) + '%',
                    (cumul / total * 100).toFixed(1) + '%'
                ]);
            }
            return this._renderDataTable(
                [t('mod2_component'), t('mod2_eigenvalue'), t('mod2_variance'), t('mod2_cumulative')],
                rows
            );
        }

        _matrixModule3() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var html = '<p style="font-size:0.9rem;color:#455a64;">' + t('mod3_matrix_note') + '</p>';
            html += this._renderMatrix(
                t('mod3_transition') + ' P',
                [
                    [t('mod3_from_new'),    '0.10', '0.70', '0.20'],
                    [t('mod3_from_active'), '0.00', '<em>r</em>',  '<em>1\u2212r</em>'],
                    [t('mod3_from_churned'),'<em>q</em>', '0.00',  '<em>1\u2212q</em>']
                ]
            );
            html += '<p style="font-size:0.85rem;color:#78909c;margin-top:8px;">' + t('mod3_vars_note') + '</p>';
            return html;
        }

        _matrixModule4() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var html = this._renderMatrix(
                t('mod4_io_matrix') + ' A',
                [
                    ['0.20', '0.30'],
                    ['0.10', '0.20']
                ]
            );
            html += this._renderMatrix(
                t('mod4_leontief') + ' (I\u2212A)\u207B\u00B9',
                [
                    ['1.3115', '0.4918'],
                    ['0.1639', '1.3115']
                ]
            );
            html += '<p style="font-size:0.9rem;color:#455a64;margin-top:8px;">' + t('mod4_target_note') + '</p>';
            return html;
        }

        _matrixModule5() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var sv = [10.0, 5.0, 2.0, 0.5, 0.1];
            var totalEnergy = 0;
            for (var i = 0; i < sv.length; i++) totalEnergy += sv[i] * sv[i];
            var cumul = 0;
            var rows = [];
            for (var i = 0; i < sv.length; i++) {
                cumul += sv[i] * sv[i];
                rows.push([
                    '\u03C3' + (i + 1),
                    sv[i].toFixed(1),
                    (sv[i] * sv[i]).toFixed(2),
                    (cumul / totalEnergy * 100).toFixed(1) + '%'
                ]);
            }
            return this._renderDataTable(
                [t('mod5_sv'), t('mod5_value'), t('mod5_energy'), t('mod5_cumulative')],
                rows
            );
        }

        // ── Dynamic UI ───────────────────────────────────────────
        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.MODULES.length - 1);
            var mod = this.MODULES[idx];
            var t = window.mySimulation.t.bind(window.mySimulation);

            var titleEl = document.getElementById('moduleTitle');
            if (titleEl) titleEl.textContent = t(mod.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(mod.briefKey);

            var matrixEl = document.getElementById('matrixDisplay');
            if (matrixEl && mod.matrixFn && typeof this[mod.matrixFn] === 'function') {
                matrixEl.innerHTML = this[mod.matrixFn]();
            }

            var input1 = document.getElementById('input1');
            var input1Label = document.getElementById('input1Label');
            var input1Hint = document.getElementById('input1Hint');
            if (input1) {
                input1.min = mod.input1Min;
                input1.max = mod.input1Max;
                input1.step = mod.input1Step;
                input1.value = mod.input1Default;
            }
            if (input1Label) input1Label.textContent = t(mod.input1Key);
            if (input1Hint) input1Hint.textContent = t(mod.input1Hint);

            var input2Group = document.getElementById('input2Group');
            var input2 = document.getElementById('input2');
            var input2Label = document.getElementById('input2Label');
            var input2Hint = document.getElementById('input2Hint');
            if (input2Group) input2Group.style.display = mod.input2Visible ? 'block' : 'none';
            if (mod.input2Visible && input2) {
                input2.min = mod.input2Min;
                input2.max = mod.input2Max;
                input2.step = mod.input2Step;
                input2.value = mod.input2Default;
            }
            if (mod.input2Visible && input2Label) input2Label.textContent = t(mod.input2Key);
            if (mod.input2Visible && input2Hint) input2Hint.textContent = t(mod.input2Hint);

            var preview = document.getElementById('livePreview');
            if (preview) preview.innerHTML = '';

            var feedback = document.getElementById('feedbackPanel');
            if (feedback) feedback.style.display = 'none';
            this._updateLivePreview();
        }

        // ── Calculation helpers ──────────────────────────────────
        _calcModule1(d) {
            var w = [d.input1 / 100, d.input2 / 100, 0];
            w[2] = Math.max(0, 1 - w[0] - w[1]);
            var mu = [0.12, 0.04, 0.08];
            var cov = [
                [0.0400, 0.0060, 0.0120],
                [0.0060, 0.0025, 0.0030],
                [0.0120, 0.0030, 0.0225]
            ];
            var portReturn = 0;
            for (var i = 0; i < 3; i++) portReturn += w[i] * mu[i];
            var portVar = 0;
            for (var i = 0; i < 3; i++) {
                for (var j = 0; j < 3; j++) {
                    portVar += w[i] * w[j] * cov[i][j];
                }
            }
            var portRisk = Math.sqrt(Math.max(0, portVar));
            var rf = 0.02;
            var sharpe = portRisk > 0 ? (portReturn - rf) / portRisk : 0;
            var score = Math.min(20, Math.round(sharpe / 0.55 * 20));
            return {
                portReturn: portReturn,
                portRisk: portRisk,
                sharpe: sharpe,
                weights: [w[0], w[1], w[2]],
                score: Math.max(0, score)
            };
        }

        _calcModule2(d) {
            var eigenvalues = [3.20, 1.80, 0.60, 0.25, 0.10, 0.05];
            var total = 6.0;
            var k = Math.max(1, Math.min(6, d.input1));
            var explained = 0;
            for (var i = 0; i < k; i++) explained += eigenvalues[i];
            var ratio = explained / total;
            var score = 0;
            if (k === 2) score = 20;
            else if (k === 3) score = 15;
            else if (k === 1) score = 10;
            else if (k === 4) score = 8;
            else score = 5;
            return {
                k: k,
                explainedVariance: ratio,
                infoLoss: 1 - ratio,
                score: score
            };
        }

        _calcModule3(d) {
            var r = d.input1 / 100;
            var q = d.input2 / 100;
            var P = [
                [0.10, 0.70, 0.20],
                [0.00, r,    1 - r],
                [q,    0.00, 1 - q]
            ];
            var state_vec = [1.0, 0.0, 0.0];
            for (var iter = 0; iter < 100; iter++) {
                var next = [0, 0, 0];
                for (var j = 0; j < 3; j++) {
                    for (var i = 0; i < 3; i++) {
                        next[j] += state_vec[i] * P[i][j];
                    }
                }
                state_vec = next;
            }
            var activeRate = state_vec[1];
            var score = Math.min(20, Math.round(activeRate / 0.778 * 20));
            return {
                steadyNew: state_vec[0],
                steadyActive: state_vec[1],
                steadyChurned: state_vec[2],
                score: Math.max(0, score)
            };
        }

        _calcModule4(d) {
            var d1 = d.input1;
            var d2 = d.input2;
            var det = 0.61;
            var inv00 = 0.8 / det;
            var inv01 = 0.3 / det;
            var inv10 = 0.1 / det;
            var inv11 = 0.8 / det;
            var x1 = inv00 * d1 + inv01 * d2;
            var x2 = inv10 * d1 + inv11 * d2;
            var target1 = 600;
            var target2 = 500;
            var dist = Math.sqrt(Math.pow(x1 - target1, 2) + Math.pow(x2 - target2, 2));
            var score = Math.max(0, Math.min(20, Math.round(20 * Math.max(0, 1 - dist / 400))));
            return {
                totalOutput1: x1,
                totalOutput2: x2,
                target1: target1,
                target2: target2,
                distance: dist,
                score: score
            };
        }

        _calcModule5(d) {
            var sv = [10.0, 5.0, 2.0, 0.5, 0.1];
            var totalEnergy = 0;
            for (var i = 0; i < sv.length; i++) totalEnergy += sv[i] * sv[i];
            var k = Math.max(1, Math.min(5, d.input1));
            var captured = 0;
            for (var i = 0; i < k; i++) captured += sv[i] * sv[i];
            var accuracy = captured / totalEnergy;
            var complexityCost = k * 3;
            var efficiencyScore = accuracy * 100 - complexityCost;
            var score;
            if (k === 2) score = 20;
            else if (k === 3) score = 17;
            else if (k === 1) score = 12;
            else if (k === 4) score = 10;
            else score = 7;
            return {
                k: k,
                accuracy: accuracy,
                complexityCost: complexityCost,
                efficiencyScore: efficiencyScore,
                score: score
            };
        }

