            } else if (idx === 1) {
                result = this._calcModule2(d);
                metricLabel = t('mod2_explained') + ': ' + (result.explainedVariance * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod2_fb_components') + ': <strong>' + result.k + '</strong></p>';
                feedbackHtml += '<p>' + t('mod2_fb_explained') + ': <strong>' + (result.explainedVariance * 100).toFixed(1) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod2_fb_loss') + ': <strong>' + (result.infoLoss * 100).toFixed(1) + '%</strong></p>';
            } else if (idx === 2) {
                result = this._calcModule3(d);
                metricLabel = t('mod3_active') + ': ' + (result.steadyActive * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod3_fb_steady') + ':</p>';
                feedbackHtml += '<p>New: <strong>' + (result.steadyNew * 100).toFixed(1) + '%</strong> | ';
                feedbackHtml += 'Active: <strong>' + (result.steadyActive * 100).toFixed(1) + '%</strong> | ';
                feedbackHtml += 'Churned: <strong>' + (result.steadyChurned * 100).toFixed(1) + '%</strong></p>';
            } else if (idx === 3) {
                result = this._calcModule4(d);
                metricLabel = t('mod4_dist') + ': ' + result.distance.toFixed(0);
                feedbackHtml = '<p>' + t('mod4_fb_output') + ':</p>';
                feedbackHtml += '<p>' + t('mod4_mfg') + ': <strong>' + result.totalOutput1.toFixed(0) + '</strong> (' + t('mod4_target') + ': ' + result.target1 + ')</p>';
                feedbackHtml += '<p>' + t('mod4_svc') + ': <strong>' + result.totalOutput2.toFixed(0) + '</strong> (' + t('mod4_target') + ': ' + result.target2 + ')</p>';
            } else {
                result = this._calcModule5(d);
                metricLabel = t('mod5_accuracy_lbl') + ': ' + (result.accuracy * 100).toFixed(1) + '%';
                feedbackHtml = '<p>' + t('mod5_fb_rank') + ': <strong>' + result.k + '</strong></p>';
                feedbackHtml += '<p>' + t('mod5_fb_accuracy') + ': <strong>' + (result.accuracy * 100).toFixed(1) + '%</strong></p>';
                feedbackHtml += '<p>' + t('mod5_fb_efficiency') + ': <strong>' + result.efficiencyScore.toFixed(1) + '</strong></p>';
            }

            var moduleScore = result.score;

            state.domainState.scoreHistory[idx] = moduleScore;
            state.domainState.scoreHistory.length = idx + 1;
            state.domainState.moduleNames[idx] = t(this.MODULES[idx].titleKey);
            state.domainState.moduleNames.length = idx + 1;
            state.domainState.totalScore = state.domainState.scoreHistory.reduce(function (a, b) { return a + (b || 0); }, 0);
            state.domainState.lastModuleScore = moduleScore;
            state.domainState.lastMetric = metricLabel;

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                var cssClass = moduleScore >= 15 ? 'feedback-good' : (moduleScore >= 10 ? 'feedback-ok' : 'feedback-poor');
                feedbackPanel.className = 'linalg-sim-feedback' + (moduleScore >= 15 ? '' : (moduleScore >= 10 ? ' fb-ok' : ' fb-poor'));
