                feedbackPanel.style.display = 'block';
            }

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 600);

            return {
                period: state.currentPeriod,
                module: idx + 1,
                moduleScore: moduleScore,
                metricLabel: metricLabel,
                totalScore: state.domainState.totalScore,
                input1: d.input1,
                input2: this.MODULES[idx].input2Visible ? d.input2 : null
            };
        }

